func ptrShipmentControl(p unsafe.Pointer, c int32) any {
	r := (*shipmentcontrol.ShipmentControl)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.MaxShipmentWeightLimit
	case 4:
		return &r.AutoDelayShipments
	case 5:
		return &r.AutoDelayShipmentsThreshold
	case 6:
		return &r.DetentionThreshold
	case 7:
		return &r.AutoCancelShipmentsThreshold
	case 8:
		return &r.AutoCancelShipments
	case 9:
		return &r.TrackDetentionTime
	case 10:
		return &r.AutoGenerateDetentionCharges
	case 11:
		return (**string)(unsafe.Pointer(&r.DetentionChargeID))
	case 12:
		return &r.UseDetentionPolicyEngine
	case 13:
		return (**string)(unsafe.Pointer(&r.DefaultDetentionPolicyID))
	case 14:
		return &r.TrackCustomerRejections
	case 15:
		return &r.CheckForDuplicateBOLs
	case 16:
		return &r.AllowMoveRemovals
	case 17:
		return &r.CheckHazmatSegregation
	case 18:
		return &r.Version
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueShipmentControl(p unsafe.Pointer, c int32) any {
	r := (*shipmentcontrol.ShipmentControl)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.MaxShipmentWeightLimit
	case 4:
		return r.AutoDelayShipments
	case 5:
		if r.AutoDelayShipmentsThreshold == nil {
			return nil
		}
		return *r.AutoDelayShipmentsThreshold
	case 6:
		if r.DetentionThreshold == nil {
			return nil
		}
		return *r.DetentionThreshold
	case 7:
		if r.AutoCancelShipmentsThreshold == nil {
			return nil
		}
		return *r.AutoCancelShipmentsThreshold
	case 8:
		return r.AutoCancelShipments
	case 9:
		return r.TrackDetentionTime
	case 10:
		return r.AutoGenerateDetentionCharges
	case 11:
		if r.DetentionChargeID == nil {
			return nil
		}
		return string(*r.DetentionChargeID)
	case 12:
		return r.UseDetentionPolicyEngine
	case 13:
		if r.DefaultDetentionPolicyID == nil {
			return nil
		}
		return string(*r.DefaultDetentionPolicyID)
	case 14:
		return r.TrackCustomerRejections
	case 15:
		return r.CheckForDuplicateBOLs
	case 16:
		return r.AllowMoveRemovals
	case 17:
		return r.CheckHazmatSegregation
	case 18:
		return r.Version
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

